metadata.er-schema:
{
  "title": "looply · 售后模块 实体关系图",
  "version": "v1.3 · 2026-07-31",
  "tables": [
    {
      "name": "after_sale_policy",
      "comment": "售后政策",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "适用市场（→ market）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "scope_type",
          "comment": "适用范围类型（全市场/品类/商品）",
          "constraint": ""
        },
        {
          "name": "scope_value",
          "comment": "适用范围值（品类或商品标识）",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级（仅同层级内多条命中时定序，越大越优先）",
          "constraint": ""
        },
        {
          "name": "is_returnable",
          "comment": "是否支持退货（特价/定制件例外）",
          "constraint": ""
        },
        {
          "name": "valid_days",
          "comment": "售后时效天数（签收后 N 天；未签收不计时）",
          "constraint": ""
        },
        {
          "name": "service_fee_amount",
          "comment": "退货服务费金额（A14）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "return_address",
          "comment": "退货地址（完整文本，按 market 配）",
          "constraint": ""
        },
        {
          "name": "policy_status",
          "comment": "政策状态（启用/停用）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A5 可配置策略实体；A17 按 market 独立配。政策匹配按【商品 → 品类 → 市场】固定层级顺序查找，匹配即停、不再往上找；该层级顺序由系统硬编码，不由 priority 决定。priority 仅用于同一层级内多条同时命中时的定序（越大越优先），例：一件商品同属「手袋」与「特价清仓」两个品类、两条品类级政策都命中时靠它定先后。数值均为运营配置项，产品阶段不定具体值"
    },
    {
      "name": "after_sale_reason",
      "comment": "售后原因码",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "reason_code",
          "comment": "原因码",
          "constraint": "UNIQUE"
        },
        {
          "name": "display_text",
          "comment": "展示文案（英文）",
          "constraint": ""
        },
        {
          "name": "apply_as_type",
          "comment": "适用售后类型（退货退款/仅退款）",
          "constraint": ""
        },
        {
          "name": "require_evidence",
          "comment": "是否必传举证",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        },
        {
          "name": "reason_status",
          "comment": "启用状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "结构化原因码。原因码不参与判责、不与金额挂钩，故不设 default_liability 字段（无消费方）。展示文案为英文，PRD 定义即最终展示文案"
    },
    {
      "name": "after_sale_order",
      "comment": "售后单（聚合根）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "as_no",
          "comment": "售后单号（编码规则归技术侧定）",
          "constraint": "UNIQUE"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_item_id",
          "comment": "订单商品行（→ order_item，一单一行）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "申请人（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "所属市场（V1 由 user 信息判定）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "policy_id",
          "comment": "命中的售后政策（→ after_sale_policy）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "policy_snapshot",
          "comment": "政策快照（建单时整条政策留档，2.1）",
          "constraint": ""
        },
        {
          "name": "as_type",
          "comment": "售后类型（退货退款/仅退款，A6/A13）",
          "constraint": ""
        },
        {
          "name": "reason_code",
          "comment": "原因码（→ after_sale_reason）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "reason_note",
          "comment": "买家补充说明",
          "constraint": ""
        },
        {
          "name": "liability_party",
          "comment": "责任归属（平台/买家）—— 仅退款审核时判，其余判责时判",
          "constraint": ""
        },
        {
          "name": "as_status",
          "comment": "售后单状态（7 个枚举：待审核/待寄回/退货在途/待判责/退款中/已完成/已关闭）",
          "constraint": ""
        },
        {
          "name": "service_fee_quoted",
          "comment": "申请时告知的服务费（退货退款取政策值；仅退款存 0）",
          "constraint": ""
        },
        {
          "name": "is_overdue_approved",
          "comment": "是否超期人工特批",
          "constraint": ""
        },
        {
          "name": "overdue_approve_note",
          "comment": "特批原因",
          "constraint": ""
        },
        {
          "name": "shipment_ref_id",
          "comment": "退货运单（→ shipments.shipment_id，弱引用）",
          "constraint": ""
        },
        {
          "name": "return_tracking_no",
          "comment": "退货运单号（运营登记值）",
          "constraint": ""
        },
        {
          "name": "return_carrier_code",
          "comment": "退货承运商编码（运营登记值）",
          "constraint": ""
        },
        {
          "name": "audit_result",
          "comment": "最近一次审核结论（通过/驳回；买家重新提交时清空）",
          "constraint": ""
        },
        {
          "name": "audit_note",
          "comment": "审核意见/驳回原因",
          "constraint": ""
        },
        {
          "name": "reject_count",
          "comment": "被驳回次数（每次驳回 +1，判「是否曾被驳回」）⚠字段形态为设计推断、非用户拍板口径，待确认",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "最近处理人",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "处理人类型（运营/系统）",
          "constraint": ""
        },
        {
          "name": "applied_at",
          "comment": "申请时间",
          "constraint": ""
        },
        {
          "name": "audited_at",
          "comment": "审核时间",
          "constraint": ""
        },
        {
          "name": "closed_at",
          "comment": "关闭时间",
          "constraint": ""
        },
        {
          "name": "close_reason",
          "comment": "关闭原因（买家撤销 / 运营关闭 / 拒退关单）",
          "constraint": ""
        },
        {
          "name": "close_notify_buyer",
          "comment": "关闭时是否邮件告知买家（12.3 运营手动勾选；默认值待定；仅运营关闭写值，买家撤销/拒退关单取 NULL 还是 false 待 PRD 确认）",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "完成时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A1 一单一行：一个商品行一张单，一次退多件=多张单。A2 不走订单域 refund_request。互斥：同一 order_item_id 同时只允许一张非终态单。⚠ 互斥占用的解除是【进入终态的必然结果，与关闭来源无关】——两个终态（已完成/已关闭）、三种关闭来源（买家撤销/运营关闭/拒退关单）一律释放，无任何例外、也不需要显式反写字段；占用与否按 order_item_id 实时聚合本域非终态单得出（与 A12 同一口径）。service_fee_quoted 是申请时告知买家的金额快照（A14 要求申请前告知），政策改价不影响在途单。market_id：订单域目前无 market 维度，V1 由 user 信息判定所属 market（已在订单侧记待优化：需补 market）。币种不冗余——售后是同一笔交易的逆向，币种必然继承订单，仅在 after_sale_refund 保留一个用于与支付域对账"
    },
    {
      "name": "after_sale_inspection",
      "comment": "验货记录",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "after_sale_order_id",
          "comment": "所属售后单（→ after_sale_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "inspection_result",
          "comment": "验货结论（含「退回途中丢件」结论值）",
          "constraint": ""
        },
        {
          "name": "inspection_note",
          "comment": "验货备注（可疑情况的唯一承载，S1；丢件原因也写这里；内部字段，不对 C 端展示）",
          "constraint": ""
        },
        {
          "name": "deduct_amount",
          "comment": "验货扣减金额",
          "constraint": ""
        },
        {
          "name": "deduct_reason",
          "comment": "扣减原因",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "录入人（运营）",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "录入人类型",
          "constraint": ""
        },
        {
          "name": "inspected_at",
          "comment": "判责提交时间（即验货结论录入时间）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A16 验货在线下仓完成、结果回传在线表格，本表承接运营录入的结论，不承接作业过程。本表由「判责」这一个动作一次性写入：运营在同一次提交里录验货结论 + 判责任方 + 填退款金额，责任方落 after_sale_order.liability_party、金额落 after_sale_refund，三者同一次提交、不分步。判责入口有两个状态：退货在途（货未到仓即可判，如退回途中丢件）与待判责（货已送达）。仅退款分支无实物验货，不产生本表记录。S1 定 V1 不做真伪复核：无「真伪存疑」结论值、无挂起态，可疑情况只写 inspection_note；inspection_note 是内部字段、不对 C 端展示。A3 只记客观结果，不含处置决策。deduct_amount 币种继承订单，不冗余存储"
    },
    {
      "name": "after_sale_refund",
      "comment": "退款方案与执行",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "after_sale_order_id",
          "comment": "所属售后单（→ after_sale_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_id",
          "comment": "所属订单（冗余，供税费累计校验）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "base_amount",
          "comment": "退款基准（商品行实付）",
          "constraint": ""
        },
        {
          "name": "service_fee_amount",
          "comment": "退货服务费实扣（运营手填，系统不算）",
          "constraint": ""
        },
        {
          "name": "deduct_amount",
          "comment": "验货扣减金额",
          "constraint": ""
        },
        {
          "name": "refund_tax_amount",
          "comment": "退还税费（★本期订单税费恒为 0，字段预留）",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "最终退款金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "refund_ref_no",
          "comment": "支付域退款单号（→ refund_order.refund_no）",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款执行状态（含失败；失败单重试与筛选的依据）",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "定案人",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "定案人类型",
          "constraint": ""
        },
        {
          "name": "refunded_at",
          "comment": "退款到账时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A2 直接对接支付域退款单，只存 refund_ref_no 不冗余金额。本表在「判责」提交时创建：判责动作本身即调用支付域退款接口，售后单随之进入「退款中」，收到退款成功结果后售后单才落「已完成」。退款失败不新增售后单主状态——失败的单停留在「退款中」可重试，失败原因与重试依据本表 refund_status 及 refund_ref_no 关联的支付域退款单状态。税费随退款退还，refund_tax_amount 用于按 order_id 做已退税费累计校验（支付域只校验金额总额、不拆税）。order_id 为冗余字段，专供该累计校验"
    },
    {
      "name": "after_sale_attachment",
      "comment": "售后附件",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "after_sale_order_id",
          "comment": "所属售后单（→ after_sale_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "inspection_id",
          "comment": "所属验货记录（验货取证时填）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_type",
          "comment": "来源（买家举证/验货取证）",
          "constraint": ""
        },
        {
          "name": "file_url",
          "comment": "文件地址",
          "constraint": ""
        },
        {
          "name": "file_type",
          "comment": "文件类型（图片/视频）",
          "constraint": ""
        },
        {
          "name": "uploader_id",
          "comment": "上传人",
          "constraint": ""
        },
        {
          "name": "uploader_type",
          "comment": "上传人类型（买家/运营）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "上传时间",
          "constraint": ""
        }
      ],
      "note": "买家在 C 端自助上传举证；运营从在线表格取图上传验货取证。两种来源靠 source_type 区分。举证必须跟单走且带审计，不能只留在外部表格。约束：inspection_id 非空时，其所属售后单必须与 after_sale_order_id 一致。保留 inspection_id 而非只挂售后单——验货照片的父本来就是那次验货，且未来若允许复验（inspection 变 1:N）该字段必需"
    },
    {
      "name": "order",
      "comment": "订单（订单域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_no",
          "comment": "订单号",
          "constraint": "UNIQUE"
        }
      ],
      "note": "外部拥有，售后只读 + 反写商品行退款状态"
    },
    {
      "name": "order_item",
      "comment": "订单商品行（订单域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_status",
          "comment": "退款状态（售后域按既有语义反写）",
          "constraint": ""
        },
        {
          "name": "fulfillment_status",
          "comment": "发货状态（售后只读不改写；入口以已发货为界）",
          "constraint": ""
        },
        {
          "name": "condition_grade",
          "comment": "成色等级快照（验货比对基准）",
          "constraint": ""
        }
      ],
      "note": "售后判责提交、调起退款（售后单进入「退款中」）才置 refund_status=退款中，到账置已退款；不在申请或审核通过时置。A12 订单表不为售后新增状态字段，「售后中」由订单侧实时查本域聚合"
    },
    {
      "name": "refund_order",
      "comment": "退款单（支付域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_no",
          "comment": "退款单号（售后弱引用）",
          "constraint": "UNIQUE"
        }
      ],
      "note": "A2 售后单直接对接本表。只存 refund_no 引用，不冗余金额。注意：订单域的 refund_request 仅服务发货前退款，售后不使用它"
    },
    {
      "name": "shipments",
      "comment": "物流运单（物流信息服务）",
      "columns": [
        {
          "name": "shipment_id",
          "comment": "运单 UUID（对外主键，不可变）",
          "constraint": "UNIQUE"
        },
        {
          "name": "business_order_no",
          "comment": "业务单号（非唯一索引，售后传订单号）",
          "constraint": ""
        },
        {
          "name": "internal_status",
          "comment": "标准化物流状态（已送达=到仓时点唯一来源）",
          "constraint": ""
        }
      ],
      "note": "A15 售后注册退货运单后获得轨迹与主动通知。business_order_no 为非唯一索引，故 1 订单号 = N 运单，支撑 A1「多张售后单共用一个退货运单号」。售后存 shipment_id 取轨迹，另落 return_tracking_no/return_carrier_code 作运营登记留痕。登记值不随物流侧修正自动同步——它记「当时登记了什么」，实时状态仍以本表为准"
    },
    {
      "name": "market",
      "comment": "销售市场（Market）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "A17 V1 覆盖美国站 + 香港站，时效/服务费/退货地址三项按 market 独立配置"
    },
    {
      "name": "user_account",
      "comment": "用户（登录注册域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部拥有，售后只读"
    }
  ],
  "relations": [
    {
      "from": "market",
      "to": "after_sale_policy",
      "type": "1:N",
